// Edit these filters to change which companies Apollo returns.
// Each run uses 1 Apollo credit per page of results.
return [{
  json: {
    organization_locations: ['United Kingdom', 'Ireland', 'Netherlands', 'Germany'],
    organization_num_employees_ranges: ['51,200', '201,500'],
    per_page: 25,
    page: 1,
  },
}];

// Turn Apollo's response into one clean item per company, keyed by domain.
const res = $input.first().json;
const orgs = [...(res.organizations || []), ...(res.accounts || [])];

const normaliseDomain = (raw) => (raw || '')
  .toLowerCase().trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const seen = new Set();
const out = [];
for (const o of orgs) {
  const domain = normaliseDomain(o.primary_domain || o.domain || o.website_url);
  if (!domain || seen.has(domain)) continue;
  seen.add(domain);
  out.push({
    json: {
      name: (o.name || '').trim(),
      domain,
      website: `https://${domain}`,
      headcount: o.estimated_num_employees ?? null,
      country: o.country || '',
      industry: o.industry || '',
    },
  });
}
return out;

// Drop companies whose website is already on an Account in Salesforce.
const normaliseDomain = (raw) => (raw || '')
  .toLowerCase().trim()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const existing = new Set(
  $input.all().map((i) => normaliseDomain(i.json.Website)).filter(Boolean),
);
const companies = $('Normalise companies').all();
const fresh = companies.filter((i) => !existing.has(i.json.domain));

console.log(`${companies.length} from Apollo, ${companies.length - fresh.length} already in Salesforce, ${fresh.length} new`);
return fresh.map((i) => ({ json: i.json }));
